"""Unit 1: Tagalog Basic Course, Semester I, Unit 1, Chapter 1, Introductory Lesson 1 (Day 1).
Original lessons; the scope follows the DLIFLC Tagalog Basic Course (Teacher Edition, November 2020).
Audio, video, pictures, partner and group activities are left out. Where the book prints an abbreviation
(G., Gng., Bb.) the spoken Tagalog here writes the full word; the English notes are mine."""
from dsl_tl import *

# ------------------------------------------------------------------ 1 greetings
_TIME = [("Magandang umaga.", "Good morning. (midnight to 11:59 a.m.)"), ("Magandang tanghali.", "Good noon. (noon to 12:59 p.m.)"), ("Magandang hapon.", "Good afternoon. (1:00 p.m. to 5:59 p.m.)"), ("Magandang gabi.", "Good evening. (6:00 p.m. to 11:59 p.m.)")]
_D1 = [("Remy", "Magandang umaga po, Ginoong Cruz.", "Good morning, sir, Mr. Cruz."), ("Ginoong Cruz", "Magandang umaga naman, Remy.", "Good morning to you too, Remy."),
       ("Nicko", "Magandang tanghali ho, Binibining Legazpi.", "Good noon, Ms. Legazpi."), ("Binibining Legazpi", "Magandang tanghali rin, Nicko.", "Good noon to you too, Nicko."),
       ("Carlo", "Magandang hapon po, Ginang de la Fuente.", "Good afternoon, Mrs. De la Fuente."), ("Ginang de la Fuente", "Magandang hapon din, Carlo.", "Good afternoon to you too, Carlo.")]
_D2 = [("Sarhento", "Magandang umaga ho, Kapitan Robles. Ako ho si Sarhento Morales. Taga-Virginia po ako.", "Good morning, Captain Robles. I am Sergeant Morales. I am from Virginia."), ("Kapitan", "Magandang umaga naman, Sarhento.", "Good morning to you too, Sergeant."),
       ("Lino", "Magandang tanghali po, Ginang Yu. Ako po si Lino. Taga-Alaska po ako.", "Good noon, Mrs. Yu. I am Lino. I am from Alaska."), ("Ginang Yu", "Magandang tanghali rin, Lino.", "Good noon to you too, Lino."),
       ("Regina", "Magandang hapon, Greg. Ako si Regina. Taga-New York.", "Good afternoon, Greg. I am Regina. From New York."), ("Greg", "Magandang hapon din, Regina.", "Good afternoon to you too, Regina.")]
_D3 = [("Marcelo", "Magandang gabi po, ma’am.", "Good evening, ma’am."), ("Melanie", "Magandang gabi naman.", "Good evening to you too."), ("Marcelo", "Ako po si Marcelo. Taga-Canada po ako.", "I am Marcelo. I am from Canada."), ("Melanie", "Kumusta ka?", "How are you?"), ("Marcelo", "Mabuti po.", "I am fine, ma’am."),
       ("Michael", "Magandang tanghali ho, Binibining Tilde.", "Good noon, Ms. Tilde."), ("Binibining Tilde", "Magandang tanghali rin.", "Good noon to you too."), ("Michael", "Ako ho si Michael. Taga-Minnesota ho ako.", "I am Michael. I am from Minnesota."), ("Binibining Tilde", "Kamusta ka, Michael?", "How are you, Michael?"), ("Michael", "Mabuti ho.", "Fine.")]
_GV = [("Ginoo", "Mister (Mr.), written G."), ("Binibini", "Miss (Ms.), written Bb."), ("Ginang", "Mrs., written Gng."), ("naman", "also"), ("din", "also (after a word that ends in a consonant)"), ("rin", "also (after a word that ends in a vowel)"), ("Kapitan", "Captain"), ("Sarhento", "Sergeant"), ("Ako", "I"), ("Kumusta ka?", "How are you? (also Kamusta ka?)"), ("Mabuti po.", "I am fine, ma’am/sir. (also Mabuti ho.)")]
L1 = lesson(
    "C1 L1 · Greetings, titles and saying who you are",
    "Magandang umaga · po and ho · Ako si · Taga- · Kumusta ka? · naman, rin, din",
    requires=[],
    cards=[
        card("Four greetings for the time of day", "English has three greetings for the time of day; Tagalog has four. The book gives the hours: midnight to 11:59 a.m. is magandang umaga; noon to 12:59 p.m. is magandang tanghali; 1:00 to 5:59 p.m. is magandang hapon; 6:00 to 11:59 p.m. is magandang gabi. Mind the stress: hápon (afternoon) is not Hapón (Japanese). In the video, po is introduced as the formal, polite element.", tables=[ttable(_TIME)]),
        card("Titles, po and ho", "Titles: Ginoo (Mr., G.), Binibini (Miss or Ms., Bb.) and Ginang (Mrs., Gng.). Add the linker -ng to Ginoo and Binibini only when they are linked to a name (Ginoong Cruz, Binibing Reyes); the ng in Ginang is not a linker but part of the word. The book spells the titles with abbreviations; the spoken lines here write them out. Filipinos often use the English words as well.\n\nPo and ho show respect for elders, persons of higher rank or authority and new acquaintances. Ho is slightly less formal than po, used with people you are comfortable with; in informal settings they are interchangeable.", tables=[ttable([("Ginoong Cruz", "Mr. Cruz"), ("Binibining Reyes", "Ms. Reyes"), ("Ginang Yu", "Mrs. Yu"), ("Magandang umaga po.", "Good morning, sir/ma’am."), ("Magandang umaga ho.", "Good morning, sir/ma’am. (slightly less formal)")])]),
        card("Also: naman, rin and din", "Naman is an enclitic with many uses; here it means “also/too” in a reply to a greeting. Rin and din both mean “also”: use rin when the word before it ends with a vowel (Magandang tanghali rin) and din when it ends with a consonant (Magandang hapon din). The book says naman will be explained in later units.", examples=dlg(_D1[:2] + _D1[2:4])),
        card("Saying who you are and where you are from", "Ako si + name means “I am + name”. There is no verb “to be”: the marker si goes in front of a person’s name. To say where you are from, use Taga + place (short answer: “From + place”) or Taga + place + ako (long answer: “I am from + place”). Po or ho goes after the first word or at the end when you speak to a superior.", examples=passage([("Ako si Roger.", "I am Roger."), ("Taga-California ako.", "I am from California."), ("Taga-California.", "From California."), ("Ako po si Marcelo.", "I am Marcelo, sir/ma’am."), ("Taga-Canada po ako.", "I am from Canada, sir/ma’am.")])),
        card("Practice dialogs", "The book’s models for pair work (Activities 4 and 5). Names and places are as in the book; “G. Cruz”, “Gng. Yu” and “Bb. Tilde” are written out in full.", examples=dlg(_D2 + _D3)),
        card("Words of the lesson", "", tables=[ttable(_GV)]),
        card("Activities left out", "Activity 2 (Listening, video 001 on greetings), the transcription Activity 6 (audio 007: magandang gabi, magandang umaga, magandang tanghali, mabuti naman, kumusta, magandang hapon, taga-Maynila ako, ginang, binibini, ginoong), and the pair-work role plays."),
    ],
    exercises=uniq(
        tr_q(_TIME) + [M("It is 3:00 in the afternoon. Which greeting fits?", "Magandang hapon.", ["Magandang umaga.", "Magandang tanghali.", "Magandang gabi."], "1:00 to 5:59 p.m. is hapon."), M("It is 8:00 in the evening. Which greeting fits?", "Magandang gabi.", ["Magandang umaga.", "Magandang hapon.", "Magandang tanghali."], "6:00 p.m. to 11:59 p.m. is gabi."), M("It is 9:00 in the morning. Which greeting fits?", "Magandang umaga.", ["Magandang gabi.", "Magandang tanghali.", "Magandang hapon."], "Midnight to 11:59 a.m. is umaga."), M("It is 12:30 p.m. Which greeting fits?", "Magandang tanghali.", ["Magandang umaga.", "Magandang hapon.", "Magandang gabi."], "Noon to 12:59 p.m. is tanghali."),
         M("How do you say “I am Roger.”?", "Ako si Roger.", ["Ako ang Roger.", "Taga-Roger ako.", "Si Roger ang ako."], "Ako si + name."), M("How do you say “I am from California.”?", "Taga-California ako.", ["Ako si California.", "Taga ako California.", "Sa California si ako."], "Taga + place + ako."), M("What does po show?", "Respect", ["A question", "The past tense", "Plural"], "Po is the polite element."), M("What does naman mean in “Magandang umaga naman”?", "Also, too", ["Never", "Please", "Not"], "A reply to a greeting."), M("What does Kumusta ka? mean?", "How are you?", ["What is your name?", "Where are you from?", "Good morning."], "Kumusta ka?"),
         M("Which word is used for “also” after a word that ends in a vowel (tanghali)?", "rin", ["din", "naman", "po"], "Rin after a vowel, din after a consonant."), M("Which word is used for “also” after a word that ends in a consonant (hapon)?", "din", ["rin", "po", "ako"], "Din after a consonant."), M("Which title means “Mrs.”?", "Ginang", ["Ginoo", "Binibini", "Kapitan"], "Ginang = Mrs. (Gng.)."), M("Which title means “Mister”?", "Ginoo", ["Ginang", "Binibini", "Sarhento"], "Ginoo = Mr. (G.)."), M("Which title means “Miss”?", "Binibini", ["Ginang", "Ginoo", "Kapitan"], "Binibini = Miss/Ms. (Bb.).")]
        + [F("Magandang tanghali ___, Binibining Tilde. (also)", "rin", ["din", "ako"], "Tanghali ends in a vowel: rin."), F("Magandang hapon ___, Carlo. (also)", "din", ["rin", "ako"], "Hapon ends in a consonant: din."), F("Ako ___ Roger. (marker before a name)", "si", ["ang", "ng"], "Ako si + name."), F("___ ako. (from California)", "Taga-California", ["Si California", "Ako California"], "Taga + place."), F("Magandang umaga ___, Kapitan Robles. (polite)", "po", ["si", "ko"], "Po shows respect."), F("Ginoo + the linker ng before a name: ___ Cruz", "Ginoong", ["Ginoo", "Ginoong ang"], "Ginoo takes -ng before a name.")]
        + tr_q(_GV[:7]) + rev_q(_GV[:7])
    ),
)

# ------------------------------------------------------------------ 2 alphabet and vowels
_VOW = [("aso", "dog"), ("ako", "I, me"), ("ate", "older sister"), ("letra", "letter"), ("tenga", "ear"), ("berde", "green"), ("isa", "one"), ("itim", "black"), ("ilog", "river"), ("oso", "bear"), ("baboy", "pig"), ("bilog", "round"), ("pusa", "cat"), ("puso", "heart"), ("pusit", "squid")]
_DIPH = [("giliw", "affection, love"), ("aliw", "entertainment"), ("baliw", "crazy, foolish"), ("liwaliw", "pleasure trip, diversion"), ("wansuy", "parsley"), ("kasuy", "cashew"), ("tsapsuy", "chop suey"), ("simoy", "breeze"), ("biloy", "dimple"), ("kahoy", "wood"), ("kumunoy", "quicksand"), ("bagay", "thing, object"), ("bahay", "house"), ("buhay", "life"), ("kamay", "hand"), ("sabaw", "broth"), ("araw", "day, sun"), ("langaw", "fly"), ("sayaw", "dance"), ("reyna", "queen"), ("beynte", "twenty"), ("beybi", "baby")]
_BORR = [("litson", "roast pig (ch = ts)"), ("litsugas", "lettuce (ch = ts)"), ("tsinelas", "slippers (ch = ts)"), ("Quiapo", "a district of Manila (qu = k)"), ("Quezon", "a province and city (qu = k)"), ("Zamboanga", "a city in Mindanao (z = s)"), ("Zamora", "a surname (z = s)")]
_SEQ = [("paa", "foot"), ("taon", "year"), ("daan", "road, way"), ("saan", "where"), ("leeg", "neck"), ("poon", "lord, master"), ("mabait", "kind"), ("doon", "over there"), ("maalat", "salty"), ("mataas", "tall"), ("kailan", "when"), ("maaari", "can, may (permission)"), ("look", "bay")]
_GLOT = [("kataga", "katagâ", "word"), ("paso", "pasô", "flower pot"), ("bigla", "biglâ", "sudden"), ("maikli", "maiklî", "short"), ("pako", "pakô", "fern"), ("mali", "malî", "mistake, wrong, error"), ("puno", "punô", "full")]
_MILD = [("baga", "baga", "ember"), ("baga", "bagà", "lungs"), ("suka", "suka", "vomit"), ("suka", "sukà", "vinegar"), ("sala", "sala", "fault, crime, sin"), ("sala", "salà", "sieve"), ("bata", "bata (de baño)", "bath robe"), ("bata", "batà", "child")]
L2 = lesson(
    "C1 L1 · The alphabet and the Tagalog vowels",
    "Abakada · five vowels · diphthongs · borrowed letters · glottal stops · vowel sequences",
    requires=[],
    cards=[
        card("The alphabet", "The Tagalog alphabet (traditionally the Abakada) has 28 letters: the 26 English letters plus Ñ (en-yeh) and NG (en-gee). C, F, J, Ñ, Q, V, X and Z are mostly used for names of people and places and for words not native to the language. Tagalog has 16 consonant sounds (counting the glottal stop, shown as a stress mark), 5 vowel sounds and 5 diphthongs. There are no silent letters, and diacritical marks are not used in ordinary writing and printing.\n\nA Aa, B Bb, C Cc, D Dd, E Ee, F Ff, G Gg, H Hh, I Ii, J Jj, K Kk, L Ll, M Mm, N Nn, Ñ ñ, NG ng, O Oo, P Pp, Q Qq, R Rr, S Ss, T Tt, U Uu, V Vv, W Ww, X Xx, Y Yy, Z Zz."),
        card("The five vowels", "A is as in alms, palm, far; E as in end, pet, set; I as in nip, cliff, hit; O as in obey, order, boy; U as in food, mood, wood.", tables=[ttable(_VOW)]),
        card("Diphthongs", "The five diphthongs are written iw, uy, oy, ay and aw (plus ey in a few borrowed words).", tables=[ttable(_DIPH)]),
        card("Letters borrowed from English and Spanish", "These letters are used in their original form and pronounced like their English or Spanish counterparts, or they are adapted by changing the spelling: C is K (Castro, Cruz); CH is TS (litson, litsugas, tsinelas); J is J (Joseph, jeep) or H (José, Juan, Jolo); LL is LY (calle, Castillo); Ñ is NY (España, Muñoz, Los Baños); Q(u) is K (Quiapo, Quezon); X is S (Xenia, xylophone) or KS (Ajax, taxi); Z is S (Zamora, Zenaida, Zamboanga).", tables=[ttable(_BORR)]),
        card("Glottal stops and vowel sequences", "The acute glottal stop (maragsâ, marked â) is the sound that begins English words such as is, and, action, and over, but unlike English it occurs at the end of Tagalog words: katagâ, pasô, biglâ, maiklî, pakô, malî, punô. The mild glottal stop (malumi, marked à) is a real phoneme that tells apart words spelled the same: baga (ember) and bagà (lungs); suka (vomit) and sukà (vinegar); sala (fault, crime, sin) and salà (sieve); bata (bath robe) and batà (child). The marks are used here only to show the stop, not in ordinary spelling; the first column is what is spoken.\n\nWhen two or more vowel sounds come one after the other, each vowel is pronounced as a distinct unit, and there are no silent letters. Stress is shown in the syllabication: paa (pa-á), taon (ta-ón), daan (da-án), saan (sa-án), leeg (le-ég), poon (po-ón), mabait (ma-ba-ít), doon (do-ón), maalat (ma-á-lat), mataas (ma-ta-ás), kailan (ka-i-lán), maaari (ma-a-á-ri), look (lo-ók).", tables=[table(["Spoken", "With the mark", "English"], [list(r) for r in _GLOT + _MILD], say=[0]), ttable(_SEQ)]),
    ],
    exercises=uniq(
        tr_q(_VOW) + tr_q(_DIPH[:12]) + tr_q(_SEQ) + rev_q(_VOW[:9]) + rev_q(_SEQ[:8])
        + [M("How many letters does the Tagalog alphabet have?", "28", ["26", "27", "30"], "The 26 English letters plus Ñ and NG."), M("Which two letters are added to the 26 English letters?", "Ñ and NG", ["CH and LL", "KH and TS", "Ñ and LL"], "Ñ (en-yeh) and NG (en-gee)."), M("What is the traditional name of the Tagalog alphabet?", "Abakada", ["Alibata", "Pilipino", "Baybayin"], "Abakada."), M("How is CH pronounced in Tagalog spelling such as litson?", "TS", ["K", "SH", "H"], "ch is written ts."), M("How is Q(u) pronounced in Quiapo?", "K", ["KW", "S", "Q as in queen"], "Q(u) is k."), M("What is the difference between baga and bagà?", "Ember and lungs", ["Dog and cat", "House and hand", "Ember and ember"], "The mild glottal stop changes the meaning."), M("What does sukà mean?", "vinegar", ["vomit", "sieve", "child"], "suka (vomit); sukà (vinegar)."), M("What does batà mean?", "child", ["bath robe", "lungs", "sieve"], "bata (bath robe); batà (child)."), M("Are any letters silent in Tagalog?", "No, there are no silent letters", ["Yes, the final vowel", "Yes, h", "Yes, ng"], "There are no silent letters in Tagalog.")]
        + [F("Ang ___ ay puti. (cat)", "pusa", ["puso", "pusit"], "pusa is cat; puso is heart; pusit is squid."), F("Ang ___ ay sa dibdib. (heart)", "puso", ["pusa", "pusit"], "puso = heart."), F("Ako ay may ___. (a house)", "bahay", ["buhay", "kamay"], "bahay = house; buhay = life; kamay = hand."), F("Ang ___ ay may tubig. (a river)", "ilog", ["oso", "itim"], "ilog = river.")]
    ),
)

