_R = [("rin", "also"), ("respeto", "respect"), ("retrato", "photo, picture"), ("kura paroko", "parish priest"), ("karinderya", "small restaurant, cafeteria"), ("bapor", "ship")]
_TDNS = [("pantay", "even"), ("panday", "blacksmith"), ("tama", "right"), ("dama", "maid of honor; game of checkers"), ("tuta", "puppy"), ("duda", "doubt"), ("nanay", "mother"), ("sanay", "expert"), ("mana", "inheritance"), ("sana", "hope"), ("nawa", "may it be so"), ("sawa", "boa constrictor")]
_PAIRS = [("papa", "father"), ("baba", "to go down"), ("sutsot", "hiss"), ("sudsod", "plowshare"), ("bulak", "cotton"), ("bulag", "blind"), ("salo", "to join"), ("halo", "to mix"), ("mais", "corn"), ("nais", "want"), ("nayon", "village"), ("ngayon", "now, today"), ("naman", "also, too"), ("laman", "contents"), ("dampa", "hut"), ("rampa", "ramp"), ("kalat", "mess"), ("karat", "karat"), ("wakwak", "ripped"), ("yakyak", "foolish or empty talk")]
_NG = [("ngayon", "now"), ("ngiti", "smile"), ("ngipin", "tooth"), ("ngitngit", "irritation"), ("ngabngab", "biting off meat from bones"), ("ngalngal", "wailing"), ("ngalay", "numbness"), ("ngakngak", "gossip, useless talk"), ("ngalangala", "palate"), ("nga", "really, please"), ("mabango", "fragrant"), ("sanga", "branch"), ("bunga", "fruit")]
