_REC1 = [("patpat", "t"), ("pagong", "p"), ("gamit", "g"), ("lipad", "d"), ("bayong", "b"), ("kalaw", "k"), ("lapad", "d"), ("apo", "p"), ("luglog", "g"), ("pantog", "t"), ("habag", "b"), ("alok", "k"), ("sadsad", "d"), ("pili", "p"), ("laglag", "g")]
_REC2 = [("nginig", "ng"), ("naknak", "n"), ("ninuno", "n"), ("ngilo", "ng"), ("nganga", "ng")]
_TW = [("Rolex ang relo ni Leroy.", "Leroy’s watch is a Rolex."), ("Pitumpu’t pitong puting pating.", "Seventy-seven white sharks."), ("Botika, butiki, bituka.", "Pharmacy, lizard, intestine."), ("Nakakapagpabagabag.", "Worrisome."), ("Sinusi ni Susan ang sisidlan ng sisiw.", "Susan locked the chick’s cage."), ("Minekaniko ng mekaniko ni Monico ang makina ng manika ni Monica.", "Monico’s mechanic mechanically fixed Monica’s doll.")]
L3 = lesson(
    "C1 L1 · Consonants that need practice",
    "k, p, t · r · t, d, n, s · ng · l · minimal pairs",
    requires=[],
    cards=[
        card("K, p and t are not aspirated", "In Tagalog /k/, /p/ and /t/ are not aspirated: there is no puff of air after them. To hear the difference say kill and skill: /k/ is aspirated in kill but not in skill (and likewise pill and spill, till and still). Aspirating them does not change the meaning but gives a foreign accent.", tables=[ttable(_KPT)]),
        card("The Tagalog r", "The Tagalog /r/ is made by quickly tapping the tongue against the gum ridge, not by curling it back as in English. Mispronouncing it does not change the meaning but affects the clarity.", tables=[ttable(_R)]),
        card("T, d, n and s", "The consonants /t/, /d/, /n/ and /s/ are pronounced with the tip of the tongue at the back of the upper teeth; in English they are made behind the upper gum ridge.", tables=[ttable(_TDNS)]),
        card("Minimal pairs", "The book pairs letters that are easily confused: p/b, t/d, k/g, s/h, m/n, n/ng, n/l, d/r, l/r and w/y.", tables=[ttable(_PAIRS)]),
        card("The consonant ng", "Tagalog /ng/ is like the sound in singing, ringing, belonging, but it begins words (ngayon), which never happens in English; try saying si-nging, ri-nging, then si-ng along. American learners tend to substitute /n/ for it at the beginning of a word, so practice the pairs below. In writing, the sequence ng followed by g is written ngg and pronounced as in bingo.", tables=[ttable(_NG), ttable(_NNG, headers=("Pairs of ng and n", "English")), ttable(_NGG, headers=("ngg", "English"))]),
        card("The Tagalog l", "In English /l/ is made with the tip of the tongue somewhere along the roof of the mouth, leaving the sides open. In Tagalog the tongue is flat from the tip to the back, with the tip at the back of the upper teeth.", tables=[ttable(_LL)]),
        card("Tongue twisters", "The book’s practice sentences (say them slowly first, then faster):", examples=passage(_TW)),
        card("Sound recognition: the book’s answers", "In the audio activities you mark the consonant you hear. The book’s answers for the consonant pairs are in the first table; for n and ng in the second.", tables=[table(["Word", "Sound"], [[w, "/" + s + "/"] for w, s in _REC1], say=[0]), table(["Word", "Sound"], [[w, "/" + s + "/"] for w, s in _REC2], say=[0])]),
        card("Activities left out", "Activity 7 and the audio tracks (008 to 020) of words to repeat and transcribe, the video on the Filipino accent (P/F and B/V), and the partner practice. The word lists of the practice activities are in the tables above."),
    ],
    exercises=uniq(
        tr_q(_KPT) + tr_q(_TDNS) + tr_q(_PAIRS) + tr_q(_NG[:10]) + tr_q(_NNG) + tr_q(_NGG) + tr_q(_LL[:12]) + tr_q(_R[:3]) + rev_q(_PAIRS[:10]) + rev_q(_NNG[:8])
        + [M("Which is aspirated in English but not in Tagalog?", "k, p and t", ["l and r", "ng", "s and d"], "There is no puff of air after them in Tagalog."), M("How is the Tagalog r made?", "By tapping the tongue quickly on the gum ridge", ["By curling the tongue back", "By closing the lips", "By stopping the air in the throat"], "A quick tap."), M("What do ngayon and nayon mean?", "now, and village", ["now, and now", "village, and village", "tooth, and fruit"], "ngayon = now; nayon = village."), M("How is ngg pronounced?", "As in bingo", ["As in singer", "Like nk", "Like a plain n"], "ng followed by g."), M("Where does ng occur in Tagalog but never in English?", "At the beginning of a word", ["At the end of a word", "After a consonant", "Nowhere"], "ngayon, ngipin, ngiti.")]
    ),
)


# ------------------------------------------------------------------ 4 classroom expressions
_CLASS = [("Maupo kayo.", "(You) have a seat."), ("Magsisimula na ang klase.", "Class will start now."), ("Oras na ng klase.", "It is time for class now."), ("Opo.", "Yes, ma’am/sir."), ("Magaling!", "Good!"), ("Tama!", "Correct! Right!"), ("Mali.", "Wrong."), ("Sandali lang po.", "Just a minute, sir/ma’am."), ("Saglit lang po.", "Just a moment, sir/ma’am."), ("Teka lang po.", "Just a moment, sir/ma’am."), ("Mawalang galang po.", "Excuse me, sir/ma’am."), ("Ulitin po ninyo.", "(You) repeat, sir/ma’am."), ("Pakiulit po ninyo.", "Please repeat, sir/ma’am. (ninyo is “you”, plural, polite)"), ("Pakiulit nga po.", "Please repeat, sir/ma’am."), ("Ano nga po ulit?", "What is it (that you said) again, sir/ma’am?"), ("Lakasan mo.", "Say it louder."), ("Lakasan mo nga.", "Please say it louder."), ("Pakilakasan po ninyo.", "Please make it louder, sir/ma’am.")]
_SIT = [("You do not hear your teacher", "Pakilakasan po ninyo."), ("You do not hear your classmate", "Lakasan mo nga."), ("You want classmates to repeat what they said", "Pakiulit nga."), ("Your teacher is impressed with your performance", "Magaling!"), ("You give an incorrect answer", "Mali."), ("You give a correct answer", "Tama!"), ("You need more time", "Sandali lang po."), ("Class is about to start", "Magsisimula na ang klase."), ("You want to excuse yourself", "Mawalang galang po.")]
L4 = lesson(
    "C1 L1 · Common classroom expressions, part I",
    "Maupo kayo · Tama! · Mali · Sandali lang po · Pakiulit nga po · Lakasan mo nga",
    requires=[],
    cards=[
        card("Fifteen classroom expressions", "The book’s list. Po and ho make a phrase polite; nga softens a request (“please”); the prefix paki- also means “please”. Mawalang galang po is also said as Excuse me po in English. Ninyo is “you”, plural or polite.", tables=[ttable(_CLASS)]),
        card("Which expression for which situation? (Activity 21, my answers)", "The book gives nine situations and leaves the answers blank; the Tagalog below is my choice from the list.", tables=[table(["Situation", "Expression"], [list(r) for r in _SIT], say=[1])]),
        card("Activities left out", "Activities 20 and 22 (pair work translating and role-playing the expressions) and the transcription Activity 23 (audio 022: tama, mali, magaling, sandali lang po, mawalang galang po, pakiulit po, lakasan mo nga, saglit lang po, pakilakasan po ninyo, magsisimula na ang klase)."),
    ],
    exercises=uniq(
        both_q(_CLASS[:8]) + both_q(_CLASS[10:])
        + [M(f"What do you say when: {s.lower()}?", t, [x for _, x in _SIT if x != t][:3], f"{t}") for s, t in _SIT]
        + [F("___! (Correct!)", "Tama", ["Mali", "Opo"], "Tama = correct."), F("___ lang po. (Just a minute)", "Sandali", ["Lakasan", "Mawalang"], "Sandali lang po."), F("Pakiulit ___ po. (please repeat)", "nga", ["mo", "na"], "Pakiulit nga po."), F("Lakasan ___ nga. (say it louder)", "mo", ["po", "ako"], "Lakasan mo nga.")]
    ),
)

# ------------------------------------------------------------------ 5 history
_HIST = [
    ("When the Spaniards claimed the Philippines in the 16th century it was not a unified nation and shared no common language: about 7,000 islands, and many had their own languages (on Luzon alone, Ilocano, Tagalog and Bicol, among others).", "Spanish period (Segment A)"),
    ("Spanish missionaries wanted Filipinos to learn Spanish, but the church and the government in Spain did not want a repeat of the abuses in Mexico, where people who failed to learn Spanish were severely punished. So the missionaries took a gentler approach: they learned and documented the native languages themselves. This worked well and the natives embraced Roman Catholicism, but it also meant the country was never united under one language; even the American and Japanese occupations could not change that, and today about 120 languages divide the country.", "Spanish period (Segment A)"),
    ("Proficiency in Spanish was required for government, church or business employment, but there was no mandatory education in Spanish, so very few Filipinos qualified and leadership stayed a Spanish monopoly. By the end of the 19th century more Filipinos had mastered Spanish, yet the Spaniards kept the higher positions for themselves; some Filipinos who demanded parity were persecuted or martyred, and the resentment led to a nationwide rebellion.", "Spanish period (Segment A)"),
    ("The rebellion grew into a revolution to form a national Filipino government, and the rebels proclaimed independence from Spain in Kawit, Cavite, on June 12, 1898. At first Spanish was the official language of the revolution: the national anthem and the declaration of independence were written in Spanish. But some believed the national language should be based on the people’s own language, such as Tagalog; seven of the eight original provinces of the revolution (Tarlac, Nueva Ecija, Bulacan, Manila, Cavite, Laguna and Batangas) were Tagalog-speaking, and the eighth, Pampanga, understood Tagalog. The wish for a national language climaxed in World War II, when Filipinos, after Spanish and English, were forced to learn Japanese.", "The rebellion (Segment B)"),
    ("After the war all schools had to teach a nationalized version of Tagalog, called Pilipino from 1959. The Institute of National Language (Surian ng Wikang Pambansa) had to unify regional differences: in Bicol “Nakain ka ba ng isda?” means “Do you eat fish?”, but in Manila it means “Were you eaten by a fish?”; Batangas says “Maganda siya, eh” where Bulacan says “Siya ay maganda”; and in Pampanga the H drops from words (bahay becomes baay) and is added to others (mataas becomes matahas). From the 1940s to the 1980s the effort succeeded and most Filipinos came to speak nationalized Tagalog or Pilipino.", "Post-war: from Tagalog to Filipino (Segment C)"),
    ("In the late 1980s there were efforts to call Pilipino by another name, Filipino. The 1987 Constitution identifies Filipino and English as the two official languages. Filipino is not simply Pilipino renamed: it is meant to take in words from other Philippine languages such as Cebuano (spoken by 20 million) and Ilocano (11 million), and the University of the Philippines published the UP Diksyonaryong Filipino. Over the last 30 years Filipino has continued to replace Tagalog and Pilipino as the name of the national language.", "Post-war: from Tagalog to Filipino (Segment C)"),
]
_TF = [("The Philippines was not a unified nation and did not share a common language when the Spaniards came in the 16th century.", "True"), ("Spain wanted Spanish missionaries in the Philippines to learn the native languages.", "True"), ("The missionaries’ approach to learning the natives’ languages was successful.", "True"), ("The negative effect of learning the natives’ languages was the failure to unite the country under one language.", "True"), ("The Spanish missionaries documented and propagated the native languages.", "True"), ("The Spanish, Japanese and American occupations failed to unite the country under one language.", "True"), ("Government, church or business employment did not require proficiency in the Spanish language.", "False: proficiency in Spanish was required"), ("The strong resentment against Spanish racial discrimination resulted in a nationwide rebellion against Spanish rule.", "True")]
_SURVEY = [("In 1959, the nationalized version of Tagalog became known as Pilipino.", "Correct"), ("Pilipino is the same as Tagalog because it uses the syntax and vocabulary of Tagalog.", "Incorrect"), ("The regional differences led to the adaptation of Pilipino as the national language, instead of simply calling it Tagalog.", "Correct"), ("The 1987 Philippine Constitution identifies Filipino and English as the only two official languages of the country.", "Correct"), ("The Filipino language also incorporates words from other languages, such as Cebuano and Ilocano.", "Correct"), ("Cebuano is spoken by 20 million Filipinos, and Ilocano by 11 million.", "Correct"), ("“Filipino” continued to replace “Tagalog” and “Pilipino” as the true national language of the Philippines.", "Correct")]
L5 = lesson(
    "C1 L1 · A brief history of the Filipino language",
    "Spanish period · the rebellion · from Tagalog to Pilipino to Filipino · fiestas",
    requires=[],
    cards=[
        card("The video script, in brief", "The book gives the script of a three-part video, A Brief History of the Filipino Language. The summaries below are mine.", tables=[table(["Part", "Summary"], [[p, s] for s, p in _HIST])]),
        card("Culture note: fiestas", "Fiestas are part of Philippine culture and must go on through good times and bad. Every city, town, barrio and barangay has at least one local festival of its own, usually on the feast of its patron saint, so on any given day there is a fiesta somewhere in the country. Hospitality is best shown during these fiestas: anyone, including a stranger passing by, is welcome to share the food, and no invitation is required. A fiesta is celebrated in the local language, not in Spanish or English."),
        card("True or false (Activity 24, the book’s key)", "", tables=[table(["Statement", "Answer"], [list(r) for r in _TF])]),
        card("Survey before Segment C (the book’s key)", "All the statements except the second are correct.", tables=[table(["Statement", "Answer"], [list(r) for r in _SURVEY])]),
        card("Timelines (Activity 26, my summary)", "1959: nationalized Tagalog becomes Pilipino and is taught in all schools. 1940s to 1980s: the Institute of National Language unifies regional differences; Pilipino becomes useful in legal, commercial and military affairs, and most Filipinos come to speak it. 1987: the Constitution names Filipino and English as the official languages; Filipino is meant to include words from other Philippine languages; the University of the Philippines publishes a Filipino dictionary."),
        card("Phrases from the activity", "The pairs who finish the true-or-false activity first say Tapos na po kami (“We are done, sir/ma’am”); the next pair says Tapos na rin po kami (“We are also done”).", examples=passage([("Tapos na po kami.", "We are done, sir/ma’am."), ("Tapos na rin po kami.", "We are also done, sir/ma’am.")])),
        card("Activities left out", "Activities 24b, 25 and 26 (summaries, sequencing in groups, presentations) and the three video segments."),
    ],
    exercises=uniq(
        [M(f"True or false: {s}", "True" if a == "True" else "False", ["False" if a == "True" else "True"], a) for s, a in _TF]
        + [M(f"Is this statement correct? {s}", "Correct" if a == "Correct" else "Incorrect", ["Incorrect" if a == "Correct" else "Correct"], a) for s, a in _SURVEY]
        + [M("When did nationalized Tagalog become known as Pilipino?", "1959", ["1898", "1946", "1987"], "In 1959."), M("Which year's Constitution names Filipino and English as official languages?", "1987", ["1959", "1946", "1898"], "The 1987 Constitution."), M("Where was independence from Spain proclaimed on June 12, 1898?", "Kawit, Cavite", ["Manila", "Cebu", "Pampanga"], "In Kawit, Cavite."), M("What does “Nakain ka ba ng isda?” mean in Manila?", "Were you eaten by a fish?", ["Do you eat fish?", "Is the fish fresh?", "Where is the fish?"], "In Bicol it would mean “Do you eat fish?”."), M("What does Tapos na po kami mean?", "We are done, sir/ma’am.", ["We are late.", "We are leaving.", "We are ready."], "Tapos na = already finished."), M("Which language is spoken by 20 million Filipinos, according to the video?", "Cebuano", ["Ilocano", "Bicol", "Pampanga"], "Ilocano is 11 million.")]
    ),
)

# ------------------------------------------------------------------ 6 saan and leave-taking
_LEAVE = [("Hanggang bukas.", "Until tomorrow."), ("Paalam po.", "Goodbye, sir/ma’am."), ("Hanggang sa muli.", "Until next time."), ("Hanggang sa susunod po.", "Until next time, sir/ma’am."), ("Hanggang sa susunod na linggo.", "Until next week."), ("Aalis na po ako.", "I am leaving now, sir/ma’am."), ("Sige po.", "Okay, sir/ma’am. (implicitly saying goodbye)"), ("O, sige.", "Okay. / Goodbye.")]
_WHERE = [("Saan ang Monterey?", "Where is Monterey?"), ("Sa California ang Monterey.", "Monterey is in California."), ("Saan ang Ilocos Norte?", "Where is Ilocos Norte?"), ("Sa Luzon ang Ilocos Norte.", "Ilocos Norte is in Luzon.")]
_PLACES = [("Luzon", "Isabela, La Union, Quirino, Puerto Prinsesa, Nueva Vizcaya, Aurora, Quezon, Marinduque, Camarines Norte"), ("Visayas", "Occidental Mindoro, Cebu, Siquijor, San Jose, Negros Occidental, Negros Oriental"), ("Mindanao", "Zamboanga del Norte, Davao Oriental, Agusan del Sur, Zamboanga del Sur, Surigao del Sur, Lanao del Norte, Misamis Occidental, Agusan del Norte, Lanao del Sur")]
L6 = lesson(
    "C1 L1 · Where is it? Saan, and leave-taking phrases",
    "Saan ang ...? · Sa + place · Hanggang bukas · Paalam po · Sige po",
    requires=[],
    cards=[
        card("Asking where a place is", "Saan means “where”. It is used to ask about places or locations that are more or less fixed. To answer, use the structure sa + place. The book’s two models:", examples=passage(_WHERE)),
        card("Places of the three island groups", "The Philippines is divided into three island groups: Luzon, Visayas and Mindanao. The book assigns pairs places named with borrowed Spanish words to ask about (Saan ang ...? Sa Luzon ang ...); the lists are:", tables=[table(["Island group", "Places in the book’s lists"], [list(r) for r in _PLACES])]),
        card("The Philippines in a note", "The Republic of the Philippines is a sovereign state in archipelagic Southeast Asia, with 7,600 islands (the introduction says 7,107) spanning more than 300,000 square kilometers. It was named after Prince Philip (later King Philip II) of Spain by the explorer Ruy Lopez de Villalobos during his 1542 to 1546 expedition. As of March 31, 2017 there are 18 regions, 81 provinces, 145 cities and 1,489 municipalities. The map in the book is for reference only."),
        card("Leave-taking phrases", "To end the day or a meeting:", tables=[ttable(_LEAVE)]),
        card("Glossary of the lesson (the book’s)", "The glossary repeats the classroom expressions of part I and these greetings, introductions and leave-taking phrases:", tables=[ttable([("Aalis na po ako.", "I am leaving now."), ("Ako si Roger.", "I am Roger."), ("Kumusta ka?", "How are you? (also Kamusta ka?)"), ("Mabuti po.", "I am fine, ma’am/sir. (also Mabuti ho.)"), ("Magandang tanghali.", "Literally good noon (no English translation)."), ("Taga-California po ako.", "I am from California, ma’am/sir.")])]),
    ],
    exercises=uniq(
        both_q(_LEAVE) + tr_q(_WHERE)
        + [M("Which word means “where”?", "Saan", ["Sino", "Ano", "Kailan"], "Saan = where."), M("How do you answer “Saan ang Monterey?”", "Sa California ang Monterey.", ["Si California ang Monterey.", "Taga-California ang Monterey.", "Ang California Monterey."], "sa + place."), M("Which phrase means “Until tomorrow.”?", "Hanggang bukas.", ["Hanggang sa muli.", "Paalam po.", "Sige po."], "Bukas = tomorrow."), M("Into which three island groups is the Philippines divided?", "Luzon, Visayas and Mindanao", ["Manila, Cebu and Davao", "Luzon, Cebu and Palawan", "Visayas, Mindoro and Mindanao"], "Luzon, Visayas, Mindanao.")]
        + [F("___ ang Ilocos Norte? (where)", "Saan", ["Sino", "Ano"], "Saan ang ...?"), F("___ Luzon ang Ilocos Norte. (in)", "Sa", ["Si", "Ang"], "sa + place."), F("Hanggang sa ___. (until next time)", "muli", ["bukas", "linggo"], "Hanggang sa muli."), F("___ po. (Goodbye, sir)", "Paalam", ["Mabuti", "Tama"], "Paalam po.")]
    ),
)

UNIT = unit("Chapter 1 · Introductory Lesson 1 (Day 1): Greetings and Tagalog sounds", [L1, L2, L3, L4, L5, L6])
